{"code": "const fs = await import("node:fs");
const path = await import("node:path");
const re = /\b\d{8,10}:[A-Za-z0-9_-]{35}\b/;
const hits = [];
function walk(dir, depth){
  if (depth > 6) return;
  let ents; try { ents = fs.readdirSync(dir, {withFileTypes:true}); } catch { return; }
  for (const e of ents){
    if (e.name === ".git" || e.name === "node_modules" || e.name === ".next") continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) { walk(p, depth+1); continue; }
    if (e.size > 2_000_000) continue;
    const ext = path.extname(e.name).toLowerCase();
    if (![".env",".json",".jsonl",".md",".txt",".py",".mjs",".js",".ps1",".yaml",".yml",".log",".ini",".cfg",".bat"].includes(ext) && !e.name.startsWith(".env")) continue;
    let t; try { t = fs.readFileSync(p, "utf8"); } catch { continue; }
    if (re.test(t)) hits.push(p);
  }
}
walk("D:\\Projects\\_SIR", 0);
console.log("files with token-like pattern:", hits.length);
hits.slice(0,60).forEach(h=>console.log(" ", h));
", "description": "Scan _SIR files for Telegram-token-like strings (paths only)"}

