const st = fs.statSync(p);
console.log("api-keys.env mtime:", st.mtime.toISOString(), "size:", st.size);
const lines = fs.readFileSync(p,"utf8").split(/\r?\n/);
const re = /\b\d{8,10}:[A-Za-z0-9_-]{35}\b/;
lines.forEach((l,i)=>{
  if (!l.trim()) return;
  const m = l.match(/^([^=]+)=(.*)$/);
  if (m){
    const k = m[1].trim(), v = m[2].trim();
    const masked = re.test(v) ? `${v.slice(0,10)}...${v.slice(-4)} (len ${v.length})` : (v.length>12? `${v.slice(0,6)}...(len ${v.length})` : `(len ${v.length})`);
    console.log(`line ${i+1}: KEY=${k} value=${masked}`);
  } else console.log(`line ${i+1}: [no key=value] ${l.slice(0,40)}`);
});
// also check whether listener reads SIR_TELEGRAM_BOT_TOKEN only from env or has fallback to a file
const lf = fs.readFileSync("D:\\Projects\\_SIR\\scripts\\deliver\\telegram-inbox.mjs","utf8");
console.log("\nlistener env token logic:");
lf.split(/\r?\n/).forEach((l,i)=>{ if(/TOKEN|token|env/i.test(l)) console.log(`${i+1}: ${l.trim()}`); });
", "description": "Inspect api-keys.env key names masked and listener token logic"}

