{"code": "const fs = await import("node:fs");
const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows"};
function exec(cmd, envExtra={}){ return new Promise(r => cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: {...ENV, ...envExtra}, windowsHide: true, maxBuffer: 10*1024*1024, timeout: 90000 }, (e,so,se)=>r({so,se,e:e&&e.message}))); }

// extract the valid token from api-keys.env (never print it)
const envText = fs.readFileSync("D:\\Projects\\_SIR\\_local\\api-keys.env","utf8");
const m = envText.match(/^TELEGRAM_SIR_AI_TOKEN=(.+)$/m);
if (!m) throw new Error("TELEGRAM_SIR_AI_TOKEN missing");
const token = m[1].trim();
// sanity: valid token
const me = await (await fetch(`https://api.telegram.org/bot${token}/getMe`, {signal: AbortSignal.timeout(20000)})).json();
console.log("getMe:", me.ok, "id:", me.result && me.result.id, "username: @"+(me.result&&me.result.username), "name:", me.result&&me.result.first_name, "canJoinGroups:", me.result&&me.result.can_join_groups);

// set user env var via child process env injection (token not on command line)
const setRes = await exec(`[Environment]::SetEnvironmentVariable('SIR_TELEGRAM_BOT_TOKEN', $env:TG_TOKEN_VALUE, 'User'); "set-ok"; [Environment]::GetEnvironmentVariable('SIR_TELEGRAM_BOT_TOKEN','User').Length`, { TG_TOKEN_VALUE: token });
console.log("set env:", setRes.so.trim(), "err:", setRes.se.trim().slice(0,300));
// verify registry length matches
const chk = await exec(`[Environment]::GetEnvironmentVariable('SIR_TELEGRAM_BOT_TOKEN','User')`);
console.log("env length now:", chk.so.trim().length, "expected:", token.length);
", "description": "Set valid SIR_TELEGRAM_BOT_TOKEN user env var"}

