{"code": "const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows"};
function exec(cmd){ return new Promise(r => cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: ENV, windowsHide: true, maxBuffer: 10*1024*1024, timeout: 45000 }, (e,so,se)=>r({so,se,e:e&&e.message}))); }
const r = await exec(`
try { Stop-Process -Id 40428 -Force -ErrorAction Stop; "stop-ok" } catch { "stop-err: " + $_.Exception.Message }
Start-Sleep -Milliseconds 900
$p = Get-Process -Id 40428 -ErrorAction SilentlyContinue
if ($p) { "still-alive" } else { "now-dead" }
"----- taskkill attempt -----"
$o = & taskkill /PID 40428 /F 2>&1 | Out-String
"taskkill out: " + $o
`);
console.log("OUT:", r.so.trim());
console.log("ERR:", r.se.slice(0,500));
", "description": "Kill old listener pid 40428 with Stop-Process and taskkill"}

