{"code": "const fs = await import("node:fs");
const path = await import("node:path");
const OPS="D:\\Projects\\_SIR\\ops";
const dir = OPS+"\\backup-manager";
const ents = fs.readdirSync(dir).map(n=>({n, t:fs.statSync(path.join(dir,n)).mtimeMs})).sort((a,b)=>b.t-a.t);
console.log("newest backup-manager files:");
for (const e of ents.slice(0,8)) console.log(" ", e.n, new Date(e.t).toISOString());
// show newest reply contents
for (const e of ents.slice(0,5)) {
  if (e.n.startsWith("reply")||e.n.startsWith("prompt")) {
    console.log("\n=== "+e.n+" ===\n"+fs.readFileSync(path.join(dir,e.n),"utf8").slice(0,1200));
  }
}
", "description": "List newest backup-manager prompt/reply files"}

