{"code": "const fs = await import("node:fs");
const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows"};
function exec(cmd){ return new Promise(r => cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: ENV, windowsHide: true, maxBuffer: 10*1024*1024, timeout: 60000 }, (e,so,se)=>r({so,se,e:e&&e.message}))); }
const OPS="D:\\Projects\\_SIR\\ops";
// listener health: process alive, log lines since restart
const r = await exec(`Get-Process -Id 21884 -ErrorAction SilentlyContinue | ForEach-Object { "alive pid " + $_.Id }`);
console.log(r.so.trim()||"NOT ALIVE");
const log = fs.readFileSync(OPS+"\\telegram-listener.log","utf8").split(/\r?\n/);
// find last occurrence of Unauthorized and count after pid restart time
const idxs = log.map((l,i)=>[l,i]).filter(([l])=>l.includes("Unauthorized"));
console.log("total Unauthorized lines:", idxs.length, "last at line:", idxs.length?idxs[idxs.length-1][1]:-1, "of", log.length);
console.log("log tail 8:\n"+log.slice(-8).join("\n"));
console.log("log mtime:", fs.statSync(OPS+"\\telegram-listener.log").mtime.toISOString());
// token in env now valid?
const me = await (await fetch(`https://api.telegram.org/bot${fs.readFileSync("D:\\Projects\\_SIR\\_local\\api-keys.env","utf8").match(/^TELEGRAM_SIR_AI_TOKEN=(.+)$/m)[1].trim()}/getMe`, {signal:AbortSignal.timeout(15000)})).json();
console.log("getMe ok:", me.ok, "@"+(me.result&&me.result.username));
", "description": "Verify listener alive and log clean after restart"}

