{"code": "async function j(url){ try { const r = await fetch(url, {signal:AbortSignal.timeout(8000)}); return {s:r.status, t: await r.text()}; } catch(e){ return {s:0, t:"ERR "+e.message}; } }
const v = await j("http://127.0.0.1:9222/json/version");
console.log("version:", v.s, v.t.slice(0,600));
const l = await j("http://127.0.0.1:9222/json/list");
if (l.s===200){ try { const tabs = JSON.parse(l.t); console.log("tabs:", tabs.length); tabs.slice(0,20).forEach(t=>console.log(" -", t.type, "|", (t.title||"").slice(0,60), "|", (t.url||"").slice(0,100))); } catch(e){ console.log(l.t.slice(0,800)); } }
", "description": "Query Chrome CDP endpoint on 9222"}

