const PS = 'C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe';
const REG = 'C:\\Windows\\System32\\reg.exe';
function userEnv(name) {
  if (process.env[name]) return process.env[name];
  for (const cmd of [
    [REG, ['query', 'HKCU\\Environment', '/v', name]],
    [PS, ['-NoProfile', '-Command', `[Environment]::GetEnvironmentVariable('${name}','User')`]],
  ]) {
    try {
      const out = execFileSync(cmd[0], cmd[1], { encoding: 'utf8', windowsHide: true, timeout: 15000 });
      const m = cmd[0] === REG ? out.match(/REG_\w+\s+(.+?)\s*$/m) : null;
      const val = (m ? m[1] : out).trim();
      if (val) return val;
    } catch {}
  }
  return '';
}
