function tryTool(label, exe, args, envExtra={}, ms=70000){
  return new Promise(resolve=>{
    const t0=Date.now();
    let out="",err="";
    const p = cp.spawn(exe, args, {env:{...ENV, ...envExtra}, windowsHide:true, stdio:["ignore","pipe","pipe"]});
    const timer = setTimeout(()=>{ try{p.kill("SIGKILL")}catch{}; resolve({label, ms:Date.now()-t0, timeout:true, out, err:err.slice(0,300)}); }, ms);
